#define _POSIX_C_SOURCE 200809L
#include "ft_common.h"
#include <rtc/rtc.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
static pthread_mutex_t output_mu=PTHREAD_MUTEX_INITIALIZER;
static int pc=-1,control=-1,file=-1;
static uint32_t sequence;
static void output(cJSON *v){char*s=cJSON_PrintUnformatted(v);pthread_mutex_lock(&output_mu);if(s){puts(s);fflush(stdout);}pthread_mutex_unlock(&output_mu);free(s);cJSON_Delete(v);}
static void description(int id,const char*sdp,const char*type,void*p){(void)id;(void)p;cJSON*v=cJSON_CreateObject();cJSON_AddStringToObject(v,"kind","description");cJSON_AddStringToObject(v,"sdp",sdp);cJSON_AddStringToObject(v,"type",type);output(v);}
static void candidate(int id,const char*value,const char*mid,void*p){(void)id;(void)p;cJSON*v=cJSON_CreateObject();cJSON_AddStringToObject(v,"kind","candidate");cJSON_AddStringToObject(v,"candidate",value);cJSON_AddStringToObject(v,"sdpMid",mid);output(v);}
static void opened(int id,void*p){(void)p;cJSON*v=cJSON_CreateObject();cJSON_AddStringToObject(v,"kind","open");cJSON_AddStringToObject(v,"channel",id==control?"control":"file");output(v);}
static void message(int id,const char*value,int size,void*p){(void)id;(void)p;cJSON*v=cJSON_CreateObject();if(size<0){cJSON_AddStringToObject(v,"kind","control");cJSON_AddItemToObject(v,"message",cJSON_Parse(value));}else{cJSON_AddStringToObject(v,"kind","binary");char*encoded=ft_base64((const unsigned char*)value,(size_t)size,false);cJSON_AddStringToObject(v,"bytes",encoded);free(encoded);}output(v);}
int main(void){rtcInitLogger(RTC_LOG_WARNING,NULL);rtcConfiguration config={0};config.disableAutoNegotiation=true;config.maxMessageSize=SE9_FT_FRAME;const char*ice=getenv("SE9_TEST_ICE");const char*servers[]={ice};if(ice&&*ice){config.iceServers=servers;config.iceServersCount=1;}if(getenv("SE9_TEST_RELAY"))config.iceTransportPolicy=RTC_TRANSPORT_POLICY_RELAY;pc=rtcCreatePeerConnection(&config);if(pc<0)return 1;rtcSetLocalDescriptionCallback(pc,description);rtcSetLocalCandidateCallback(pc,candidate);control=rtcCreateDataChannel(pc,"se9.control.v1");file=rtcCreateDataChannel(pc,"se9.file.v1");rtcSetOpenCallback(control,opened);rtcSetOpenCallback(file,opened);rtcSetMessageCallback(control,message);rtcSetMessageCallback(file,message);rtcSetLocalDescription(pc,"offer");char*line=NULL;size_t cap=0;while(getline(&line,&cap,stdin)>0){cJSON*v=cJSON_Parse(line);const char*kind=ft_string(v,"kind");int result=0;if(!strcmp(kind,"answer"))result=rtcSetRemoteDescription(pc,ft_string(v,"sdp"),"answer");else if(!strcmp(kind,"candidate"))result=rtcAddRemoteCandidate(pc,ft_string(v,"candidate"),ft_string(v,"sdpMid"));else if(!strcmp(kind,"control")){char*s=cJSON_PrintUnformatted(cJSON_GetObjectItemCaseSensitive(v,"message"));result=rtcSendMessage(control,s,-1);free(s);}else if(!strcmp(kind,"reset"))sequence=0;else if(!strcmp(kind,"block")){uint64_t index=0,length=0,epoch=0;ft_u64(v,"index",&index);ft_u64(v,"length",&length);ft_u64(v,"epoch",&epoch);if(length>SE9_FT_BLOCK){cJSON_Delete(v);return 2;}unsigned char payload[SE9_FT_FRAME-SE9_FT_HEADER],frame[SE9_FT_FRAME];for(uint64_t offset=0;offset<length;){size_t n=(size_t)(length-offset);if(n>sizeof(payload))n=sizeof(payload);for(size_t i=0;i<n;i++)payload[i]=(unsigned char)((index*SE9_FT_BLOCK+offset+i)%251);size_t bytes=ft_frame_write(frame,sizeof(frame),ft_string(v,"id"),(uint32_t)epoch,sequence++,index*SE9_FT_BLOCK+offset,payload,n);while(rtcGetBufferedAmount(file)>1024*1024){struct timespec delay={.tv_nsec=10000000};nanosleep(&delay,NULL);}result=bytes?rtcSendMessage(file,(char*)frame,(int)bytes):-1;if(result)break;offset+=n;}cJSON*out=cJSON_CreateObject();cJSON_AddStringToObject(out,"kind","sent");cJSON_AddNumberToObject(out,"result",result);output(out);}else if(!strcmp(kind,"pair")){char local[256],remote[256];result=rtcGetSelectedCandidatePair(pc,local,sizeof(local),remote,sizeof(remote));cJSON*out=cJSON_CreateObject();cJSON_AddStringToObject(out,"kind","pair");cJSON_AddStringToObject(out,"local",result<0?"":local);cJSON_AddStringToObject(out,"remote",result<0?"":remote);output(out);}else if(!strcmp(kind,"quit")){cJSON_Delete(v);break;}if(result<0){cJSON*out=cJSON_CreateObject();cJSON_AddStringToObject(out,"kind","error");cJSON_AddNumberToObject(out,"result",result);output(out);}cJSON_Delete(v);}free(line);rtcDeleteDataChannel(control);rtcDeleteDataChannel(file);rtcDeletePeerConnection(pc);rtcCleanup();return 0;}
